  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Suffering and Trust: Job$j$, $j${"questions": [{"q": "Which of these did Job lose in Job 1?", "options": ["His voice", "His children, his wealth and later his health", "Only his house", "Only his friends"]}, {"q": "What did Job say in Job 1:21?", "options": ["I will go back to Egypt", "The LORD gave, and the LORD hath taken away; blessed be the name of the LORD", "My friends are right", "I will curse God and die"]}, {"q": "What did Job's three friends wrongly believe?", "options": ["That God did not exist", "That suffering always comes from a person's own sin", "That Job was a prophet", "That Job was lazy"]}, {"q": "What hope did Job state in Job 19:25?", "options": ["That his friends would apologize", "That he would be king", "That his money would return", "That his redeemer liveth"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Suffering and Trust: Job$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,3}'::int[], array[$j$Job lost his children, his livestock and servants, and then his health.$j$,$j$Job worshipped even in his loss.$j$,$j$The friends insisted Job must have sinned, but God said they had not spoken rightly.$j$,$j$Job said, I know that my redeemer liveth.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Suffering and Trust: Job$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: The Prayer Book of Israel: Psalms$j$, $j${"questions": [{"q": "How many psalms are in the book of Psalms?", "options": ["One hundred", "Fifty", "Two hundred", "One hundred and fifty"]}, {"q": "Who wrote about half of the psalms?", "options": ["David", "Solomon", "Moses", "Isaiah"]}, {"q": "What is Hebrew parallelism?", "options": ["A prayer with no words", "Rhyming at the end of lines", "A second line that repeats, completes or contrasts the first", "A list of names"]}, {"q": "According to Psalm 119:105, what is God's word?", "options": ["A river in a dry land", "A rock in the desert", "A sword and a shield", "A lamp unto my feet, and a light unto my path"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: The Prayer Book of Israel: Psalms$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,2,3}'::int[], array[$j$The book of Psalms has 150 psalms.$j$,$j$David wrote about half of the psalms.$j$,$j$Hebrew poetry balances lines in pairs instead of depending on rhyme.$j$,$j$Psalm 119:105 says, Thy word is a lamp unto my feet, and a light unto my path.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: The Prayer Book of Israel: Psalms$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Wisdom for Daily Life: Proverbs$j$, $j${"questions": [{"q": "Who wrote most of the book of Proverbs?", "options": ["Solomon", "Moses", "Isaiah", "Paul"]}, {"q": "What does Proverbs 1:7 say is the beginning of knowledge?", "options": ["Education alone", "Hard work", "Wealth", "The fear of the LORD"]}, {"q": "What does Proverbs 15:1 say turns away wrath?", "options": ["A gift", "A soft answer", "Silence only", "A loud argument"]}, {"q": "A proverb is best understood as:", "options": ["A general truth that is usually right", "A promise that is always right", "A story about a king", "A law for the priests"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Wisdom for Daily Life: Proverbs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,0}'::int[], array[$j$Most of Proverbs was written by Solomon.$j$,$j$The fear of the LORD is the beginning of knowledge.$j$,$j$A soft answer turneth away wrath.$j$,$j$A proverb states a general truth; it is not an unconditional promise.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Wisdom for Daily Life: Proverbs$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Seasons and Love: Ecclesiastes and Song of Solomon$j$, $j${"questions": [{"q": "What word does the Preacher use to describe life apart from God?", "options": ["Peace", "Vanity", "Victory", "Joy"]}, {"q": "What does Ecclesiastes 3:1 say there is for every purpose?", "options": ["A test", "A reward", "A season", "A king"]}, {"q": "What is the conclusion of the whole matter in Ecclesiastes 12:13?", "options": ["Avoid all work", "Build great cities", "Gain wealth", "Fear God and keep his commandments"]}, {"q": "What does the Song of Solomon celebrate?", "options": ["Faithful love in marriage", "The temple", "Military victory", "The law of Moses"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Seasons and Love: Ecclesiastes and Song of Solomon$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,3,0}'::int[], array[$j$Ecclesiastes says vanity of vanities, a picture of a passing breath.$j$,$j$To every thing there is a season, and a time to every purpose under the heaven.$j$,$j$The whole duty of man is to fear God and keep His commandments.$j$,$j$It is a love poem that celebrates marriage as God's gift.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Seasons and Love: Ecclesiastes and Song of Solomon$j$ on conflict (item_id) do nothing;
